#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader amzt_xcipher;
float4 amzSample_xcipher(float2 uv) { return float4(amzt_xcipher.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xcipher(uv);return float4(0.0); }
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
uniform float amzp_AMOUNT;
uniform float amzp_SPREAD;
uniform float amzp_EVO;
uniform float amzp_EVO2;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
    float4 newLayer( float4 a, float4 b) { return a * (1. - b.a) + b; }
    float2x2 rot2m(float a){ float s = sin(a); float c = cos(a); return float2x2(c, -s, s, c); }
    float2 l2s( float2 v ) { return (float4(v,0.,1.)*amzLayerToScreen()).xy; }
        float min_dist(float2 v, float2 w, float2 p)
        {
            float t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) /
                            ((w.x - v.x) * (w.x - v.x) + (w.y - v.y) * (w.y - v.y));
            if (t < 0.0)
                return distance(p, v);
            else if (t > 1.0)
                return distance(p, w);
            float2 op = v + t * (w - v);
            return distance(p, op);
        }
        float rand(float _seed)
        {
            return fract(sin(_seed+137.0) * 43758.5453);
        }
        float ll3(float2 p1, float2 p2, float2 uv)
        {
         float2 plast;
         float mind = 1000000.0;
         plast = p1;
         float seed = rand(floor(time*40.0));
         for (int i=0; i < 2; i++)
         {
          float tt = float(i+1) / 3.0;
          float2 pt = p1 + ((p2 - p1) * tt);
          float a = rand(seed) * 3.141592 * 2.0;
          float2 pn = pt + float2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*90.0);
          float d = min_dist(plast, pn, uv);
          if (d < mind)
           mind = d;
          plast = pn;
          seed = rand(seed);
         }
         float d = min_dist(plast, p2, uv);
         if (d < mind)
          return d * 3.0;
         else
          return mind * 5.0;
        }
        float ll2(float2 p1, float2 p2, float2 uv)
        {
         float2 plast;
         float mind = 1000000.0;
         plast = p1;
         float seed = rand(floor(amzp_EVO2*15.0));
         for (int i=0; i < int(amzp_SPREAD); i++)
         {
          float tt = float(i+1) / 4.0;
          float2 pt = p1 + ((p2 - p1) * tt);
          float a = rand(seed) * 3.141592 * 2.0;
          float2 pn = pt + float2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*30.0);
          float d = min_dist(plast, pn, uv);
          if (d < mind)
           mind = d;
          float2 pn2 = pn + float2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*rand(seed)*30.0);
          d = ll3(pn, pn2, uv);
          if (d < mind)
           mind = d;
          plast = pn;
          seed = rand(seed);
         }
         float d = min_dist(plast, p2, uv);
         if (d < mind)
          return d * 3.0;
         else
          return mind * 3.0;
        }
        void amzRender() {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float2 iResolution = float2(screen.zw.x, screen.zw.y);
        float2 iMouse = float2(0.5, 0.5);
        float iTime = time;
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0+amzp_angle)*0.0174533);
        satriyaid += float2((-250.0+amzp_position.x), (140.0-amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
     float4 fragColor;
         float2 uv = satriyaid;
         float2 p1 = float2(0.1, 0.3),
           plast,
           p2 = float2(0.9, 0.3);
         float mind = 1000000.0;
         plast = p1;
         float seed = rand(floor(amzp_EVO*10.0));
         for (int i=0; i < int(amzp_AMOUNT); i++)
         {
          float tt = float(i+1) / 15.0;
          float2 pt = p1 + ((p2 - p1) * tt);
          float a = rand(seed) * 3.141592 * 2.0;
          float2 pn = pt + float2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*9.0);
          float d = min_dist(plast, pn, uv);
          if (d < mind)
           mind = d;
          float2 pn2 = pn + float2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*rand(seed)*6.0);
          d = ll2(pn, pn2, uv);
          if (d < mind)
           mind = d;
          plast = pn;
          seed = rand(seed);
         }
         float d = min_dist(plast, p2, uv);
         if (d < mind)
          mind = d;
         mind *= 10.0;
         mind += 1.0;
         mind = 1.0 / (mind*mind*mind*mind);
         fragColor = float4(1.0, 1.0, 1.0, 1.0) * mind;
         fragColor.r *= mind;
         fragColor.g *= mind;
         const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(amzp_color1,amzp_color2,luminance)*fragColor.a;
         float4 factor = mix(texColorX,gradmap,1.0);
        float4 resultfinal;
          if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_hardness) * texColor.a; }
          else if( int(amzp_blendMode)==1 ) { factor *= amzp_hardness;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
          else if( int(amzp_blendMode)==2 ) { factor *= amzp_hardness;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
          else if( int(amzp_blendMode)==3 ) { factor *= amzp_hardness;
            resultfinal = (newLayer(texColor, factor) * amzp_hardness) * texColor.a; }
     amzOutput = mix(texColor, resultfinal, amzp_alpha) * texColor.a;
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
